def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    if not np.any(valid):
        return np.full_like(bins, -np.inf, dtype=float)
    median_rem = np.median(remaining[valid])
    absolute_penalty = -np.abs(remaining - median_rem)
    return np.where(valid, absolute_penalty, -np.inf)

